import { test, expect } from '@playwright/test';

test.describe('Image Gallery Lightbox', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/gallery');
  });

  test('should open lightbox when an image is clicked', async ({ page }) => {
    const image = page.getByRole('img', { name: 'Gallery Image 1' });
    await image.click();

    const lightbox = page.getByRole('dialog', { name: 'Image Lightbox' });
    await expect(lightbox).toBeVisible();
  });

  test('should close lightbox when close button is clicked', async ({ page }) => {
    const image = page.getByRole('img', { name: 'Gallery Image 1' });
    await image.click();

    const closeButton = page.getByRole('button', { name: 'Close' });
    await closeButton.click();

    const lightbox = page.getByRole('dialog', { name: 'Image Lightbox' });
    await expect(lightbox).not.toBeVisible();
  });
});
